-- 2) Ngân hàng nhận xét ------------------------------------------------------------
create table if not exists v2.comment_bank (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references v2.profiles (id) on delete cascade,
  scope text not null check (scope ~ '^[a-z0-9][a-z0-9:._-]{0,59}$'),
  level text check (level in ('T', 'H', 'C', 'Đ')),
  text text not null check (length(btrim(text)) between 1 and 1000),
  uses int not null default 1 check (uses >= 0),
  shared boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table v2.comment_bank is 'Ngân hàng nhận xét của GV (gợi ý khi nhập nhận xét). scope: tt27:<mã môn> | tt27:chung | …';
create unique index if not exists comment_bank_uniq on v2.comment_bank (owner_id, scope, md5(lower(text)));
create index if not exists comment_bank_shared_idx on v2.comment_bank (scope) where shared;

drop trigger if exists comment_bank_updated_at on v2.comment_bank;
create trigger comment_bank_updated_at before update on v2.comment_bank for each row execute function v2.set_updated_at();

create or replace function v2._comment_bank_limit() returns trigger
language plpgsql security definer set search_path = v2, public as $$
begin
  if (select count(*) from v2.comment_bank where owner_id = new.owner_id) >= 3000 then
    raise exception 'Ngân hàng nhận xét đã đủ 3000 câu — thầy cô xoá bớt câu ít dùng nhé.' using errcode = '54000';
  end if;
  return new;
end $$;
revoke all on function v2._comment_bank_limit() from public, anon, authenticated;
drop trigger if exists comment_bank_limit on v2.comment_bank;
create trigger comment_bank_limit before insert on v2.comment_bank for each row execute function v2._comment_bank_limit();

alter table v2.comment_bank enable row level security;
drop policy if exists comment_bank_select on v2.comment_bank;
drop policy if exists comment_bank_insert on v2.comment_bank;
drop policy if exists comment_bank_update on v2.comment_bank;
drop policy if exists comment_bank_delete on v2.comment_bank;
create policy comment_bank_select on v2.comment_bank for select to authenticated
  using (owner_id = (select auth.uid()) or (shared and (select v2.is_staff())));
create policy comment_bank_insert on v2.comment_bank for insert to authenticated
  with check (owner_id = (select auth.uid()) and (select v2.is_staff()));
create policy comment_bank_update on v2.comment_bank for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy comment_bank_delete on v2.comment_bank for delete to authenticated using (owner_id = (select auth.uid()));
revoke all on v2.comment_bank from public, anon, authenticated;
grant select, insert, update, delete on v2.comment_bank to authenticated;
grant all on v2.comment_bank to service_role;

-- Lưu nhiều nhận xét một lần (trùng câu → tăng số lần dùng). p = [{ "scope": "tt27:toan", "level": "T", "text": "…" }, …]
create or replace function v2.bank_add_comments(p jsonb) returns int
language plpgsql security definer set search_path = v2, public as $$
declare e jsonb; n int := 0; v_text text; v_scope text; v_level text;
begin
  if not (select v2.is_staff()) then
    raise exception 'Chỉ thầy cô mới dùng ngân hàng nhận xét.' using errcode = '42501';
  end if;
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 500 then
    raise exception 'Danh sách nhận xét không hợp lệ (tối đa 500 câu một lần).' using errcode = '22023';
  end if;
  for e in select value from jsonb_array_elements(p) loop
    v_text := left(btrim(regexp_replace(coalesce(e ->> 'text', ''), '\s+', ' ', 'g')), 1000);
    v_scope := coalesce(e ->> 'scope', '');
    v_level := nullif(e ->> 'level', '');
    continue when v_text = '' or v_scope !~ '^[a-z0-9][a-z0-9:._-]{0,59}$' or (v_level is not null and v_level not in ('T', 'H', 'C', 'Đ'));
    insert into v2.comment_bank (owner_id, scope, level, text) values (auth.uid(), v_scope, v_level, v_text)
    on conflict (owner_id, scope, md5(lower(text))) do update
      set uses = v2.comment_bank.uses + 1, level = coalesce(excluded.level, v2.comment_bank.level), updated_at = now();
    n := n + 1;
  end loop;
  return n;
end $$;
revoke all on function v2.bank_add_comments(jsonb) from public, anon;
grant execute on function v2.bank_add_comments(jsonb) to authenticated;

-- 3) Thông tin bổ sung của học sinh --------------------------------------------------
create table if not exists v2.student_notes (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references v2.profiles (id) on delete cascade,
  category text not null default 'khac' check (category in ('quan-sat', 'hoc-tap', 'suc-khoe', 'gia-dinh', 'nang-khieu', 'khen-thuong', 'khac')),
  title text not null check (length(btrim(title)) between 1 and 200),
  body text not null default '' check (length(body) <= 20000),
  fields jsonb not null default '{}'::jsonb check (jsonb_typeof(fields) = 'object' and pg_column_size(fields) <= 16384),
  note_date date not null default current_date,
  source text not null default 'tay' check (source in ('tay', 'word', 'excel')),
  source_name text check (source_name is null or length(source_name) <= 200),
  share_parent boolean not null default false,
  created_by uuid default auth.uid() references v2.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
comment on table v2.student_notes is 'Thông tin bổ sung GV nhập cho học sinh (nhập tay / Word / Excel). Phụ huynh chỉ thấy khi share_parent.';
create index if not exists student_notes_student_idx on v2.student_notes (student_id, note_date desc);

drop trigger if exists student_notes_updated_at on v2.student_notes;
create trigger student_notes_updated_at before update on v2.student_notes for each row execute function v2.set_updated_at();

alter table v2.student_notes enable row level security;
drop policy if exists student_notes_select on v2.student_notes;
drop policy if exists student_notes_insert on v2.student_notes;
drop policy if exists student_notes_update on v2.student_notes;
drop policy if exists student_notes_delete on v2.student_notes;
create policy student_notes_select on v2.student_notes for select to authenticated
  using ((select v2.is_teacher_of_student(student_id)) or (share_parent and (select v2.is_guardian_of(student_id))));
create policy student_notes_insert on v2.student_notes for insert to authenticated
  with check ((select v2.is_teacher_of_student(student_id)));
create policy student_notes_update on v2.student_notes for update to authenticated
  using ((select v2.is_teacher_of_student(student_id))) with check ((select v2.is_teacher_of_student(student_id)));
create policy student_notes_delete on v2.student_notes for delete to authenticated
  using ((select v2.is_teacher_of_student(student_id)));
revoke all on v2.student_notes from public, anon, authenticated;
grant select, insert, update, delete on v2.student_notes to authenticated;
grant all on v2.student_notes to service_role;

